// A small ghost/spec‐only helper: on the spec‐level sequence,
// keep exactly those elements v with v % 3 == 0.
#[verifier(spec)]
fn filter3(s: Seq<u64>) -> Seq<u64> {
    s.filter_by(|_i: nat, v: u64| v % 3 == 0)
}

/// For every call myfun4(x, y), we prove that
///   y@ == filter3(old(x)@)
/// i.e. y ends up being exactly the sub‐sequence of x
/// consisting of the multiples of 3, in order.
///
/// No other requirements are needed.
#[requires(true)]
#[ensures(y@ == filter3(old(x)@))]
pub fn myfun4(x: &Vec<u64>, y: &mut Vec<u64>) {
    // Start with empty y;
    y.clear();

    // We'll iterate by index so we can state a loop‐invariant.
    let mut i: usize = 0;

    // Loop invariant:
    //   0 <= i <= x.len()
    //   and y@ is exactly filter3(old(x)@[0..i])
    //
    // Decreases clause to ensure termination.
    #[invariant(i <= x.len())]
    #[invariant(y@ == filter3(old(x)@[0..i]))]
    #[decreases(x.len() - i)]
    while i < x.len() {
        let value = x[i];
        if value % 3 == 0 {
            y.push(value);
        }
        i += 1;
    }
}

